'use client'

import { useEffect, useId, useRef, type ReactNode } from 'react'
import './scroll-expand-hero.css'

export interface ScrollExpandHeroProps {
  eyebrow?: string
  title: string
  description?: string
  /** Decorative artwork only. Keep meaningful information in the text props. */
  media: ReactNode
  action?: { label: string; href: string }
  caption?: string
  /** Three short labels for the portrait, panorama and full-scene chapters. */
  chapters?: readonly [string, string, string]
  className?: string
}

const defaultChapters = ['Approach', 'Perspective', 'Place'] as const
const frameNames = ['PORTRAIT', 'PANORAMA', 'FULL FRAME'] as const
const clamp = (value: number) => Math.min(1, Math.max(0, value))
// Easing is tied to scroll position; it never adds momentum or captures input.
const ease = (value: number) => value * value * (3 - 2 * value)

function nearestViewport(element: HTMLElement): HTMLElement | null {
  let parent = element.parentElement
  while (parent && parent !== document.documentElement) {
    const overflow = window.getComputedStyle(parent).overflowY
    if (/(auto|scroll|overlay)/.test(overflow) && parent.scrollHeight > parent.clientHeight + 1) return parent
    parent = parent.parentElement
  }
  return null
}

function decorativeMedia(element: HTMLDivElement | null) {
  element?.setAttribute('inert', '')
}

/** A native-scroll composition that moves from portrait to panorama to full scene. */
export function ScrollExpandHero({
  eyebrow,
  title,
  description,
  media,
  action,
  caption,
  chapters = defaultChapters,
  className = '',
}: ScrollExpandHeroProps) {
  const headingId = useId()
  const rootRef = useRef<HTMLElement>(null)
  const pinRef = useRef<HTMLDivElement>(null)
  const titleRef = useRef<HTMLHeadingElement>(null)
  const descriptionRef = useRef<HTMLParagraphElement>(null)
  const footerRef = useRef<HTMLDivElement>(null)
  const railRef = useRef<HTMLDivElement>(null)
  const progressRef = useRef<HTMLProgressElement>(null)
  const frameLabelRef = useRef<HTMLSpanElement>(null)
  const chapterRef = useRef<HTMLOListElement>(null)
  const indexRef = useRef<HTMLSpanElement>(null)

  useEffect(() => {
    const root = rootRef.current
    const pin = pinRef.current
    const heading = titleRef.current
    const footer = footerRef.current
    if (!root || !pin || !heading || !footer) return
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)')
    let frame = 0
    let previousStage = -1

    function readPosition() {
      frame = 0
      if (!root || !pin || !heading || !footer) return
      const viewport = nearestViewport(root)
      const viewportTop = viewport ? viewport.getBoundingClientRect().top + viewport.clientTop : 0
      const height = viewport?.clientHeight || window.innerHeight
      const footerHeight = footer.offsetHeight
      const contentHeight = Math.ceil(Math.max(
        heading.offsetHeight / .62 + footerHeight + (railRef.current?.offsetHeight || 0) + 55,
        (descriptionRef.current?.offsetHeight || 0) / .16 + footerHeight + 40,
      ))
      root.style.setProperty('--ac-scroll-expand-view', `${height}px`)
      root.style.setProperty('--ac-scroll-expand-content-height', `${contentHeight}px`)
      root.style.setProperty('--ac-scroll-expand-footer-height', `${footerHeight}px`)
      const bounds = root.getBoundingClientRect()
      const travel = Math.max(1, bounds.height - pin.offsetHeight)
      const progress = reducedMotion.matches ? 1 : clamp((viewportTop - bounds.top) / travel)
      const opening = ease(clamp(progress / .55))
      const immersion = ease(clamp((progress - .55) / .45))
      root.style.setProperty('--ac-scroll-expand-progress', progress.toFixed(4))
      root.style.setProperty('--ac-scroll-expand-opening', opening.toFixed(4))
      root.style.setProperty('--ac-scroll-expand-immersion', immersion.toFixed(4))
      if (progressRef.current) progressRef.current.value = progress
      const stage = progress < .28 ? 0 : progress < .76 ? 1 : 2
      if (stage !== previousStage) {
        previousStage = stage
        root.dataset.stage = String(stage)
        if (frameLabelRef.current) frameLabelRef.current.textContent = `${String(stage + 1).padStart(2, '0')} / ${frameNames[stage]}`
        if (indexRef.current) indexRef.current.textContent = String(stage + 1).padStart(2, '0')
        Array.from(chapterRef.current?.children || []).forEach((chapter, index) => {
          if (index === stage) chapter.setAttribute('aria-current', 'step')
          else chapter.removeAttribute('aria-current')
        })
      }
    }

    function scheduleRead() {
      if (!frame) frame = window.requestAnimationFrame(readPosition)
    }

    document.addEventListener('scroll', scheduleRead, { capture: true, passive: true })
    window.addEventListener('scroll', scheduleRead, { passive: true })
    window.addEventListener('resize', scheduleRead)
    reducedMotion.addEventListener('change', scheduleRead)
    const resize = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(scheduleRead)
    let ancestor: HTMLElement | null = root
    while (ancestor && ancestor !== document.documentElement) {
      resize?.observe(ancestor)
      ancestor = ancestor.parentElement
    }
    for (const node of [pin, heading, footer, descriptionRef.current, railRef.current]) {
      if (node) resize?.observe(node)
    }
    readPosition()

    return () => {
      document.removeEventListener('scroll', scheduleRead, true)
      window.removeEventListener('scroll', scheduleRead)
      window.removeEventListener('resize', scheduleRead)
      reducedMotion.removeEventListener('change', scheduleRead)
      resize?.disconnect()
      window.cancelAnimationFrame(frame)
      for (const property of ['view', 'progress', 'opening', 'immersion', 'content-height', 'footer-height']) {
        root.style.removeProperty(`--ac-scroll-expand-${property}`)
      }
      delete root.dataset.stage
    }
  }, [title, description, eyebrow, action?.label, caption, chapters[0], chapters[1], chapters[2]])

  return (
    <section ref={rootRef} className={`ac-scroll-expand-hero ${className}`.trim()} aria-labelledby={headingId} data-stage="0">
      <div ref={pinRef} className="ac-scroll-expand-pin">
        <div ref={railRef} className="ac-scroll-expand-topline">
          <p>{eyebrow || 'A different perspective'}</p>
          <span aria-hidden="true"><span className="ac-scroll-expand-cross">+</span> SCENE <span ref={indexRef}>01</span> / 03</span>
        </div>
        <header className="ac-scroll-expand-copy">
          <h2 ref={titleRef} id={headingId}>{title}</h2>
        </header>
        {description && <p ref={descriptionRef} className="ac-scroll-expand-description">{description}</p>}
        <div ref={decorativeMedia} className="ac-scroll-expand-media" aria-hidden="true">
          <div className="ac-scroll-expand-art">{media}</div>
          <span ref={frameLabelRef} className="ac-scroll-expand-frame-label">01 / PORTRAIT</span>
          <span className="ac-scroll-expand-frame-cross">+</span>
        </div>
        <div ref={footerRef} className="ac-scroll-expand-footer">
          <div className="ac-scroll-expand-project">
            {caption && <p className="ac-scroll-expand-caption">{caption}</p>}
            {action && <a className="ac-scroll-expand-action" href={action.href}>{action.label}<span aria-hidden="true">↗</span></a>}
          </div>
          <ol ref={chapterRef} className="ac-scroll-expand-chapters" aria-label="Scene chapters">
            {chapters.map((chapter, index) => <li key={index} aria-current={index === 0 ? 'step' : undefined}><span aria-hidden="true">0{index + 1}</span>{chapter}</li>)}
          </ol>
          <progress ref={progressRef} className="ac-scroll-expand-progress" max={1} value={0} aria-label="Hero scene progress" />
        </div>
      </div>
    </section>
  )
}

.ac-scroll-expand-hero {
  --ac-scroll-expand-progress: 0;
  --ac-scroll-expand-opening: 0;
  --ac-scroll-expand-immersion: 0;
  --ac-scroll-expand-view: 800px;
  --ac-scroll-expand-content-height: 0px;
  --ac-scroll-expand-footer-height: 112px;
  --ac-scroll-expand-paper: var(--ac-scroll-expand-theme-paper, #131414);
  --ac-scroll-expand-ink: var(--ac-scroll-expand-theme-ink, #f3f4ee);
  --ac-scroll-expand-muted: var(--ac-scroll-expand-theme-muted, #bfc1b9);
  --ac-scroll-expand-accent: #c7ff4b;
  --ac-scroll-expand-pin-height: max(580px, calc(var(--ac-scroll-expand-view) * .97), var(--ac-scroll-expand-content-height));
  position: relative;
  min-height: calc(var(--ac-scroll-expand-pin-height) + var(--ac-scroll-expand-view) * 1.35);
  background: var(--ac-scroll-expand-paper);
  color: var(--ac-scroll-expand-ink);
  font-family: var(--ac-scroll-expand-font, Arial, Helvetica, sans-serif);
  container-type: inline-size;
  isolation: isolate;
}

.ac-scroll-expand-hero * { box-sizing: border-box; }

.ac-scroll-expand-pin {
  position: sticky;
  top: 0;
  height: var(--ac-scroll-expand-pin-height);
  overflow: hidden;
}

.ac-scroll-expand-topline {
  position: absolute;
  z-index: 4;
  top: clamp(24px, 3.4cqw, 48px);
  right: 5%;
  left: 5%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 24px;
  padding-bottom: 15px;
  border-bottom: 1px solid color-mix(in srgb, currentColor 27%, transparent);
  font-size: clamp(9px, 1cqw, 12px);
  font-weight: 500;
  letter-spacing: .06em;
  line-height: 1.4;
  text-transform: uppercase;
}
.ac-scroll-expand-topline p { margin: 0; max-width: 60%; overflow-wrap: anywhere; }
.ac-scroll-expand-topline > span { flex-shrink: 0; white-space: nowrap; }
.ac-scroll-expand-cross { margin-right: 26px; color: var(--ac-scroll-expand-accent); font-size: 20px; font-weight: 400; vertical-align: -2px; }

.ac-scroll-expand-copy {
  position: absolute;
  z-index: 1;
  top: 23%;
  left: 5%;
  width: 74%;
  transform-origin: 0 0;
  transform: translateY(calc(var(--ac-scroll-expand-opening) * -12px - var(--ac-scroll-expand-immersion) * 45px)) scale(calc(1 + var(--ac-scroll-expand-opening) * .09));
  opacity: calc(1 - var(--ac-scroll-expand-immersion) * .82);
}
.ac-scroll-expand-copy h2 {
  margin: 0;
  font-family: var(--ac-scroll-expand-heading-font, inherit);
  font-size: clamp(62px, min(14.6cqw, 20svh), 230px);
  font-weight: 400;
  line-height: .86;
  letter-spacing: -.085em;
  white-space: pre-line;
  overflow-wrap: anywhere;
}

.ac-scroll-expand-description {
  position: absolute;
  z-index: 3;
  top: 67%;
  left: 5%;
  width: min(32%, 34ch);
  margin: 0;
  color: var(--ac-scroll-expand-muted);
  font-size: clamp(11px, 1.3cqw, 16px);
  line-height: 1.5;
  text-wrap: pretty;
  opacity: calc(1 - var(--ac-scroll-expand-opening));
  transform: translateY(calc(var(--ac-scroll-expand-opening) * -16px));
}

.ac-scroll-expand-media {
  position: absolute;
  z-index: 2;
  top: calc(13% + var(--ac-scroll-expand-opening) * 11% - var(--ac-scroll-expand-immersion) * 24%);
  left: calc(57% - var(--ac-scroll-expand-opening) * 51% - var(--ac-scroll-expand-immersion) * 6%);
  width: calc(36% + var(--ac-scroll-expand-opening) * 52% + var(--ac-scroll-expand-immersion) * 12%);
  height: calc(69% - var(--ac-scroll-expand-opening) * 11% + var(--ac-scroll-expand-immersion) * 42%);
  overflow: hidden;
  background: #5a615c;
  outline: 1px solid #f3f4ee24;
  outline-offset: -1px;
}
.ac-scroll-expand-art { position: absolute; inset: 0; overflow: hidden; }
.ac-scroll-expand-art > * { display: block; width: 100%; height: 100%; }
.ac-scroll-expand-art img, .ac-scroll-expand-art video {
  object-fit: cover;
  object-position: calc(68% - var(--ac-scroll-expand-opening) * 18% + var(--ac-scroll-expand-immersion) * 5%) 50%;
  transform: scale(calc(1.14 - var(--ac-scroll-expand-opening) * .14 + var(--ac-scroll-expand-immersion) * .035));
}
.ac-scroll-expand-media::after {
  position: absolute;
  inset: 0;
  content: '';
  background: linear-gradient(180deg, #0d11139c 0%, #0d11130a 35%, #10141422 65%, #0a1014e6 100%);
  pointer-events: none;
}
.ac-scroll-expand-frame-label, .ac-scroll-expand-frame-cross { position: absolute; z-index: 1; font-size: 9px; line-height: 1; }
.ac-scroll-expand-frame-label { top: 15px; left: 15px; letter-spacing: .1em; opacity: calc(1 - var(--ac-scroll-expand-immersion)); }
.ac-scroll-expand-frame-cross { right: 12px; bottom: 9px; color: var(--ac-scroll-expand-accent); font-size: 25px; font-weight: 300; }

.ac-scroll-expand-footer {
  position: absolute;
  z-index: 4;
  right: 5%;
  bottom: 22px;
  left: 5%;
}
.ac-scroll-expand-project { display: flex; align-items: flex-end; justify-content: space-between; gap: 24px; min-height: 48px; margin-bottom: 22px; }
.ac-scroll-expand-caption {
  max-width: 36ch;
  min-width: 0;
  overflow-wrap: anywhere;
  margin: 0;
  font-size: clamp(11px, calc(1.15cqw + var(--ac-scroll-expand-immersion) * .6cqw), 24px);
  line-height: 1.3;
  letter-spacing: -.015em;
  white-space: pre-line;
}
.ac-scroll-expand-action {
  display: inline-flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
  gap: 28px;
  min-height: 44px;
  min-width: 0;
  max-width: min(55%, 32ch);
  overflow-wrap: anywhere;
  padding: 10px 0;
  border-bottom: 1px solid currentColor;
  color: inherit;
  font-size: clamp(11px, 1.15cqw, 14px);
  line-height: 1.35;
  text-decoration: none;
}
.ac-scroll-expand-action span { flex-shrink: 0; font-size: 22px; transition: transform 180ms ease; }
.ac-scroll-expand-action:hover span { transform: translate(3px, -3px); }
.ac-scroll-expand-action:focus-visible { outline: 2px solid var(--ac-scroll-expand-accent); outline-offset: 6px; }
.ac-scroll-expand-chapters { display: flex; justify-content: space-between; gap: 14px; margin: 0 0 11px; padding: 0; list-style: none; }
.ac-scroll-expand-chapters li { display: flex; gap: 13px; align-items: baseline; color: color-mix(in srgb, currentColor 65%, transparent); font-size: clamp(9px, 1cqw, 11px); line-height: 1.4; }
.ac-scroll-expand-chapters li span { font-size: 8px; }
.ac-scroll-expand-chapters [aria-current='step'] { color: var(--ac-scroll-expand-ink); }
.ac-scroll-expand-chapters [aria-current='step'] span { color: var(--ac-scroll-expand-accent); }
.ac-scroll-expand-progress { display: block; width: 100%; height: 1px; border: 0; border-radius: 0; background: color-mix(in srgb, currentColor 24%, transparent); color: var(--ac-scroll-expand-accent); appearance: none; }
.ac-scroll-expand-progress::-webkit-progress-bar { background: color-mix(in srgb, currentColor 24%, transparent); }
.ac-scroll-expand-progress::-webkit-progress-value { background: var(--ac-scroll-expand-accent); }
.ac-scroll-expand-progress::-moz-progress-bar { background: var(--ac-scroll-expand-accent); }

@container (max-width: 600px) {
  .ac-scroll-expand-hero { --ac-scroll-expand-pin-height: max(610px, calc(var(--ac-scroll-expand-view) * .97), var(--ac-scroll-expand-content-height)); }
  .ac-scroll-expand-topline { top: 24px; right: 6%; left: 6%; font-size: 8px; padding-bottom: 12px; }
  .ac-scroll-expand-cross { margin-right: 12px; font-size: 16px; }
  .ac-scroll-expand-copy { top: 16%; left: 6%; width: 88%; }
  .ac-scroll-expand-copy h2 { font-size: clamp(57px, 18.6cqw, 110px); line-height: .88; }
  .ac-scroll-expand-media {
    top: calc(38% - var(--ac-scroll-expand-opening) * 9% - var(--ac-scroll-expand-immersion) * 29%);
    left: calc(28% - var(--ac-scroll-expand-opening) * 22% - var(--ac-scroll-expand-immersion) * 6%);
    width: calc(66% + var(--ac-scroll-expand-opening) * 22% + var(--ac-scroll-expand-immersion) * 12%);
    height: calc(44% + var(--ac-scroll-expand-opening) * 11% + var(--ac-scroll-expand-immersion) * 45%);
  }
  .ac-scroll-expand-description { top: auto; bottom: calc(var(--ac-scroll-expand-footer-height) + 52px); left: 6%; width: min(66%, 27ch); color: #f3f4ee; font-size: 11px; }
  .ac-scroll-expand-footer { right: 6%; bottom: 20px; left: 6%; }
  .ac-scroll-expand-project { gap: 18px; margin-bottom: 20px; }
  .ac-scroll-expand-caption { max-width: 20ch; font-size: 11px; }
  .ac-scroll-expand-action { gap: 14px; max-width: 48%; font-size: 10px; }
  .ac-scroll-expand-chapters { gap: 10px; }
  .ac-scroll-expand-chapters li { gap: 6px; font-size: 8px; }
  .ac-scroll-expand-chapters li span { font-size: 7px; }
  .ac-scroll-expand-frame-label { top: 12px; left: 12px; font-size: 7px; }
}

@media (prefers-reduced-motion: reduce) {
  .ac-scroll-expand-hero { min-height: 0; }
  .ac-scroll-expand-pin { position: relative; min-height: max(610px, var(--ac-scroll-expand-content-height)); height: var(--ac-scroll-expand-pin-height); }
  .ac-scroll-expand-media { top: 0; left: 0; width: 100%; height: 100%; }
  .ac-scroll-expand-media::after { background: linear-gradient(180deg, #0a1014a1, #0a101433 55%, #0a1014dd); }
  .ac-scroll-expand-copy { z-index: 3; transform: none; opacity: 1; }
  .ac-scroll-expand-copy h2 { font-size: clamp(57px, 12cqw, 160px); }
  .ac-scroll-expand-art img, .ac-scroll-expand-art video { transform: none; object-position: center; }
  .ac-scroll-expand-description { top: auto; bottom: calc(var(--ac-scroll-expand-footer-height) + 52px); opacity: 1; transform: none; color: var(--ac-scroll-expand-ink); }
  .ac-scroll-expand-frame-label, .ac-scroll-expand-frame-cross { display: none; }
  .ac-scroll-expand-action span { transition: none; }
}


/* Neutral framing changes with the page; footage keeps its dark overlay. */
:where([data-theme="light"]) .ac-scroll-expand-hero { --ac-scroll-expand-theme-paper: #fafbf8; --ac-scroll-expand-theme-ink: #202722; --ac-scroll-expand-theme-muted: #687269; color-scheme: light; }
:where([data-theme="dark"], .dark) .ac-scroll-expand-hero { --ac-scroll-expand-theme-paper: #191e1b; --ac-scroll-expand-theme-ink: #edf2eb; --ac-scroll-expand-theme-muted: #a7b3a3; color-scheme: dark; }
.ac-scroll-expand-frame-label { color: #f3f4ee; }
:where([data-theme="light"]) .ac-scroll-expand-topline,
:where([data-theme="light"]) .ac-scroll-expand-footer { color: color-mix(in srgb, #202722 calc(100% - var(--ac-scroll-expand-immersion) * 100%), #f3f4ee); }
:where([data-theme="light"]) .ac-scroll-expand-chapters [aria-current='step'] { color: inherit; }
@media (prefers-reduced-motion: reduce) {
  :where([data-theme="light"]) .ac-scroll-expand-hero { --ac-scroll-expand-theme-ink: #f3f4ee; --ac-scroll-expand-theme-muted: #bfc1b9; }
  :where([data-theme="light"]) .ac-scroll-expand-topline,
  :where([data-theme="light"]) .ac-scroll-expand-footer { color: #f3f4ee; }
}
/* Keep the mobile caption readable where the partial image crosses the light page. */
@media (prefers-reduced-motion: no-preference) {
  @container (max-width: 600px) {
    :where([data-theme="light"]) .ac-scroll-expand-description {
      width: min(calc(66% + 18px), calc(27ch + 18px));
      margin-left: -9px;
      padding: 6px 8px;
      border: 1px solid #d7ded4;
      border-radius: 3px;
      background: rgb(250 251 248 / 94%);
      color: #202722;
    }
  }
}
